import {createHash} from 'node:crypto';
import {Poly} from './poly.mjs';
import {Rat} from './rational.mjs';
import {parseExpression} from './expression.mjs';
export const PROFILE='vrc.polynomial.v1';
export const hash=x=>createHash('sha256').update(typeof x==='string'?x:JSON.stringify(x)).digest('hex');
const NAME=/^[A-Za-z_][A-Za-z0-9_.-]*$/;
function tokens(s){const matches=s.match(/"(?:[^"\\]|\\.)*"|[^\s]+/g)||[];return matches.map(t=>t.startsWith('"')?JSON.parse(t):t);}
/** Command-owned SOP profile, not a parser for the entire host language. */
export function parseSOP(text,{source='memory.sop',maxDeclarations=100000}={}){
 if(typeof text!=='string')throw new TypeError('SOP source must be text');const blocks=[];let current=null;
 for(const [i,raw]of text.split(/\r?\n/).entries()){const line=raw.trim();if(!line||line.startsWith('#'))continue;
  if(line.startsWith('@')){const m=line.match(/^@([A-Za-z_][A-Za-z0-9_.-]*)\s+([A-Za-z][A-Za-z0-9_.-]*)\s*$/);if(!m)throw new SyntaxError(`${source}:${i+1}: expected @name command`);current={id:m[1],type:m[2],line:i+1,clauses:[]};blocks.push(current);if(blocks.length>maxDeclarations)throw new RangeError('Declaration budget');}
  else {if(!current)throw new SyntaxError(`${source}:${i+1}: clause outside a declaration`);current.clauses.push({text:line,line:i+1});}}
 const ids=new Set();for(const b of blocks){if(ids.has(b.id))throw new SyntaxError(`Duplicate producer @${b.id}`);ids.add(b.id);}
 const transitions=new Map(),goals=new Map(),encoders=new Map(),facts=[];
 for(const b of blocks){const get=k=>b.clauses.filter(c=>c.text===k||c.text.startsWith(k+' ')),one=(k,required=true)=>{const cs=get(k);if(cs.length!==1){if(!required&&cs.length===0)return null;throw new SyntaxError(`@${b.id}: exactly one ${k} required`);}return cs[0].text.slice(k.length).trim();};
  if(b.type==='claim'){const value=tokens(one('VALUE'));if(value[0]!=='state'||value.length!==4)throw new SyntaxError(`@${b.id}: VRC facts use VALUE state entity variable number`);const[relation,entity,variable,num]=value;if(!NAME.test(variable))throw new SyntaxError('Invalid variable name');facts.push({id:b.id,relation,entity,variable,value:Rat.of(num),source:(()=>{const v=one('SOURCE',false);return v?(v.startsWith('"')?JSON.parse(v):v):source;})(),line:b.line});for(const c of b.clauses)if(!/^(VALUE|SOURCE)\s/.test(c.text))throw new SyntaxError(`@${b.id}: unsupported claim clause`);}
  else if(b.type==='transition'){if(one('INTERPRETER')!==PROFILE)throw new SyntaxError(`@${b.id}: require INTERPRETER ${PROFILE}`);const vars=tokens(one('STATE'));if(!vars.length||new Set(vars).size!==vars.length||vars.some(v=>!NAME.test(v)||v.includes('.')||v.includes('-')))throw new SyntaxError('STATE needs unique simple names');const seen=new Set(),byVar=new Map(),fragments=[];
   for(const c of get('NEXT')){const m=c.text.match(/^NEXT\s+(\w+)\s+(.+)$/);if(!m||!vars.includes(m[1])||seen.has(m[1]))throw new SyntaxError(`@${b.id}: invalid/duplicate NEXT`);const parsed=parseExpression(m[2],vars);byVar.set(m[1],parsed.polynomial);fragments.push(...parsed.fragments);seen.add(m[1]);}
   if(seen.size!==vars.length)throw new SyntaxError(`@${b.id}: every state variable needs NEXT (identity must be explicit)`);
   const guards=get('GUARD').map(c=>{const m=c.text.slice(6).match(/^(.+?)\s+(>=|<=|==|>|<)\s+(.+)$/);if(!m)throw new SyntaxError(`@${b.id}: invalid GUARD`);return {op:m[2],poly:parseExpression(m[1],vars).polynomial.sub(parseExpression(m[3],vars).polynomial),line:c.line};});
   for(const c of b.clauses)if(!/^(INTERPRETER|STATE|NEXT|GUARD|SOURCE)\s/.test(c.text))throw new SyntaxError(`@${b.id}: unsupported transition clause ${c.text}`);
   transitions.set(b.id,{id:b.id,variables:vars,T:vars.map(v=>byVar.get(v)),guards,fragments,source:(()=>{const v=one('SOURCE',false);return v?(v.startsWith('"')?JSON.parse(v):v):source;})(),line:b.line});
  }else if(b.type==='vrc.encode'){
   if(one('INTERPRETER')!==PROFILE)throw new SyntaxError('Invalid encoder interpreter');const variables=tokens(one('STATE')),outputs=tokens(one('GIVES'));if(!variables.length||!outputs.length||[...variables,...outputs].some(v=>!/^\w+$/.test(v))||new Set(variables).size!==variables.length||new Set(outputs).size!==outputs.length)throw new SyntaxError('Encoder interface');const map=new Map();for(const c of get('BIND')){const m=c.text.match(/^BIND\s+(\w+)\s+(.+)$/);if(!m||!outputs.includes(m[1])||map.has(m[1]))throw new SyntaxError('Invalid encoder BIND');map.set(m[1],parseExpression(m[2],variables).polynomial);}if(map.size!==outputs.length)throw new SyntaxError('Incomplete encoder');for(const c of b.clauses)if(!/^(INTERPRETER|STATE|GIVES|BIND)\s/.test(c.text))throw new SyntaxError('Unsupported encoder clause');encoders.set(b.id,{id:b.id,variables,outputs,E:outputs.map(v=>map.get(v)),line:b.line});
  }else if(b.type==='goal'){if(one('INTERPRETER')!==PROFILE)throw new SyntaxError(`@${b.id}: unsupported goal interpreter`);const actions=tokens(one('USING')).map(x=>{if(!/^\$[\w.-]+$/.test(x))throw new SyntaxError('USING requires $value references');return x.slice(1);});const observation=get('OBSERVE').map(c=>c.text.slice(8).trim());if(!observation.length)throw new SyntaxError('At least one OBSERVE required');const horizon=Number(one('HORIZON',false)??'1');if(!Number.isSafeInteger(horizon)||horizon<0||horizon>1000000)throw new RangeError('Horizon budget');goals.set(b.id,{id:b.id,actions,observation,horizon,entity:(()=>{const v=one('ENTITY',false);if(v===null)return null;const ts=tokens(v);if(ts.length!==1)throw new SyntaxError('ENTITY requires one token');return ts[0];})(),encoding:one('ENCODE',false),line:b.line});for(const c of b.clauses)if(!/^(INTERPRETER|USING|OBSERVE|HORIZON|ENTITY|ENCODE)\s/.test(c.text))throw new SyntaxError(`@${b.id}: unsupported goal clause`);
  }else throw new SyntaxError(`@${b.id}: unsupported command ${b.type}; use the host interpreter for nonnumeric SOP`);
 }
 for(const goal of goals.values()){if(new Set(goal.actions).size!==goal.actions.length)throw new SyntaxError('Duplicate transition reference');const acts=goal.actions.map(id=>{const a=transitions.get(id);if(!a)throw new SyntaxError(`Unresolved $${id}`);return a;});const vars=acts[0]?.variables;if(!vars||acts.some(a=>JSON.stringify(a.variables)!==JSON.stringify(vars)))throw new SyntaxError('Actions require an identical ordered STATE interface');goal.H=goal.observation.map(s=>parseExpression(s,vars).polynomial);if(goal.encoding){if(!/^\$[\w.-]+$/.test(goal.encoding))throw new SyntaxError('ENCODE needs a $reference');const e=encoders.get(goal.encoding.slice(1));if(!e||JSON.stringify(e.outputs)!==JSON.stringify(vars))throw new SyntaxError('Encoder output interface mismatch');goal.encoder=e;}}
 const factIndex=new Map();for(const f of facts){if(!factIndex.has(f.entity))factIndex.set(f.entity,new Map());const row=factIndex.get(f.entity);if(!row.has(f.variable))row.set(f.variable,[]);row.get(f.variable).push(f);}return {profile:PROFILE,source,sourceHash:hash(text),transitions,goals,encoders,facts,factIndex};
}
export function selectGoal(program,name){const g=name?program.goals.get(name):program.goals.values().next().value;if(!g)throw new Error('Goal not found');const actions=g.actions.map(id=>program.transitions.get(id));return {goal:g,actions,variables:actions[0].variables,H:g.H};}
export function contract(program,goalName){const {goal,actions,variables,H}=selectGoal(program,goalName);return {profile:PROFILE,variables,actions:actions.map(a=>({id:a.id,T:a.T.map(p=>p.toJSON()),guards:a.guards.map(g=>({op:g.op,p:g.poly.toJSON()}))})),H:H.map(p=>p.toJSON()),encoder:goal.encoder?{variables:goal.encoder.variables,outputs:goal.encoder.outputs,E:goal.encoder.E.map(p=>p.toJSON())}:null};}
/** Only exactly one positive numeric fact per entity/variable is supported. No last-write-wins. */
export function stateFacts(program,entity,variables){const row=program.factIndex?.get(entity);const facts=row?null:program.facts.filter(f=>f.entity===entity),values=[],evidence=[];if(!row&&!facts.length)return {status:'UNKNOWN',reason:'unknown-entity',entity};for(const v of variables){const matches=row?(row.get(v)||[]):facts.filter(f=>f.variable===v);if(matches.length!==1)return {status:'UNKNOWN',reason:matches.length?'conflicting-or-duplicate-facts':'missing-fact',variable:v,entity};values.push(matches[0].value.toNumber());evidence.push({claim:matches[0].id,source:matches[0].source,line:matches[0].line,value:matches[0].value.toString()});}return {status:'OK',state:Float64Array.from(values),evidence,snapshotHash:hash(evidence)};}
export function transitionSOP(id,variables,T,guards=[]){return `@${id} transition\nINTERPRETER ${PROFILE}\nSTATE ${variables.join(' ')}\n`+T.map((p,i)=>`NEXT ${variables[i]} ${p.toString(variables)}\n`).join('')+guards.map(g=>`GUARD ${g.poly.toString(variables)} ${g.op} 0\n`).join('');}

export function resolveState(program,goalName,entity){const s=selectGoal(program,goalName),encoder=s.goal.encoder;const f=stateFacts(program,entity,encoder?encoder.variables:s.variables);if(f.status!=='OK')return f;if(!encoder)return {...f,exactState:f.evidence.map(e=>Rat.of(e.value))};const exact=encoder.E.map(p=>p.evaluateExact(f.evidence.map(e=>Rat.of(e.value))));return {...f,state:Float64Array.from(exact,r=>r.toNumber()),exactState:exact,encoding:{wire:encoder.id,formulas:encoder.E.map(p=>p.toJSON())}};}

/** Query-conditioned read. Missing values outside the certified encoding are not needed. */
export function resolveModelState(program,goalName,entity,model){const spec=selectGoal(program,goalName),pre=spec.goal.encoder,names=pre?pre.variables:spec.variables,E=pre?model.E.map(p=>p.compose(pre.E)):model.E,needed=[...new Set(E.flatMap(p=>p.variables()))].sort((a,b)=>a-b),facts=stateFacts(program,entity,needed.map(i=>names[i]));if(facts.status!=='OK')return facts;const raw=Array(names.length).fill(Rat.of(0));needed.forEach((i,j)=>raw[i]=Rat.of(facts.evidence[j].value));const state=pre?pre.E.map(p=>p.evaluateExact(raw)):raw;return {...facts,exactState:state,state:Float64Array.from(state,r=>r.toNumber()),unneededVariables:names.filter((_,i)=>!needed.includes(i)),encoding:pre?{wire:pre.id}:null};}
